import 'package:flutter/material.dart';
import 'services/app_database.dart';
import 'services/session_service.dart';

void main() async { WidgetsFlutterBinding.ensureInitialized(); await AppDatabase.instance.initialize(); runApp(const App()); }
class App extends StatelessWidget { const App({super.key}); @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'SIMMANO PENGAJIAN V1 Lite',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFF1565C0)),scaffoldBackgroundColor:const Color(0xFFF7F9FC),cardTheme:CardThemeData(color:Colors.white,elevation:0,shape:RoundedRectangleBorder(borderRadius:BorderRadius.all(Radius.circular(18))))),home:const LoginPage()); }
enum AppRole { ketua,bendahara,sekretaris,anggota }
extension RoleLabel on AppRole { String get label=>switch(this){AppRole.ketua=>'Ketua',AppRole.bendahara=>'Bendahara',AppRole.sekretaris=>'Sekretaris',AppRole.anggota=>'Anggota'}; }
class LoginPage extends StatefulWidget{const LoginPage({super.key});State<LoginPage> createState()=>_LoginPageState();}
class _LoginPageState extends State<LoginPage>{final n=TextEditingController();AppRole role=AppRole.ketua;bool loading=false;Future<void> login()async{if(n.text.trim().isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Nama pengguna wajib diisi.')));return;}setState(()=>loading=true);await SessionService.instance.login(n.text.trim(),role);if(!mounted)return;Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>HomePage(name:n.text.trim(),role:role)));}Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:460),child:Column(children:[Container(width:double.infinity,padding:const EdgeInsets.all(24),decoration:BoxDecoration(color:Theme.of(c).colorScheme.primary,borderRadius:BorderRadius.circular(28)),child:const Column(children:[Icon(Icons.mosque,size:60,color:Colors.white),SizedBox(height:10),Text('SIMMANO PENGAJIAN V1 Lite',style:TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.bold),textAlign:TextAlign.center),SizedBox(height:6),Text('Sederhana digunakan • Transparan dikelola • Histori aman',style:TextStyle(color:Colors.white70),textAlign:TextAlign.center)])),const SizedBox(height:28),const Align(alignment:Alignment.centerLeft,child:Text('Masuk ke aplikasi',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold))),const SizedBox(height:14),TextField(controller:n,decoration:const InputDecoration(labelText:'Nama pengguna',prefixIcon:Icon(Icons.person_outline))),const SizedBox(height:14),DropdownButtonFormField<AppRole>(value:role,decoration:const InputDecoration(labelText:'Peran',prefixIcon:Icon(Icons.badge_outlined)),items:AppRole.values.map((r)=>DropdownMenuItem(value:r,child:Text(r.label))).toList(),onChanged:(v){if(v!=null)setState(()=>role=v);}),const SizedBox(height:22),FilledButton(onPressed:loading?null:login,style:FilledButton.styleFrom(minimumSize:const Size.fromHeight(54)),child:loading?const CircularProgressIndicator():const Text('Masuk'))]))))));}
class HomePage extends StatefulWidget{final String name;final AppRole role;const HomePage({super.key,required this.name,required this.role});State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{int index=0;@override Widget build(BuildContext c){final pages=[DashboardPage(name:widget.name),GroupsPage(role:widget.role),MembersPage(role:widget.role),const PlaceholderPage(title:'Jadwal Pengajian'),const MorePage()];return Scaffold(appBar:AppBar(title:const Text('SIMMANO PENGAJIAN'),actions:[IconButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ProfilePage(name:widget.name,role:widget.role))),icon:const Icon(Icons.account_circle_outlined))]),body:pages[index],bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(i)=>setState(()=>index=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'Beranda'),NavigationDestination(icon:Icon(Icons.groups_outlined),label:'Kelompok'),NavigationDestination(icon:Icon(Icons.people_outline),label:'Anggota'),NavigationDestination(icon:Icon(Icons.event_outlined),label:'Jadwal'),NavigationDestination(icon:Icon(Icons.more_horiz),label:'Lainnya') ]));}}
class DashboardPage extends StatelessWidget{final String name;const DashboardPage({super.key,required this.name});Widget stat(String a,String b,IconData i)=>Expanded(child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Icon(i,size:28),const SizedBox(height:8),Text(a),Text(b,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold))]))));Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Text('Assalamu’alaikum, $name',style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:18),Row(children:[stat('Anggota','0',Icons.people),const SizedBox(width:10),stat('Kelompok','0',Icons.groups)]),Row(children:[stat('Saldo Kas','Rp 0',Icons.account_balance_wallet),const SizedBox(width:10),stat('Jadwal','0',Icons.event)]),const Card(child:Padding(padding:EdgeInsets.all(18),child:Text('Bagian 02 aktif: Kelompok, Subkelompok, Anggota, dan Riwayat Keanggotaan.',style:TextStyle(fontSize:16))))]);}
class GroupsPage extends StatefulWidget{final AppRole role;const GroupsPage({super.key,required this.role});State<GroupsPage> createState()=>_GroupsPageState();}
class _GroupsPageState extends State<GroupsPage>{List<Map<String,Object?>> data=[];int? selected;List<Map<String,Object?>> subs=[];@override void initState(){super.initState();load();}Future<void> load()async{final d=await AppDatabase.instance.groups();setState(()=>data=d);if(selected!=null)loadSubs(selected!);}Future<void> loadSubs(int id)async{final s=await AppDatabase.instance.subgroups(id);setState(()=>subs=s);}Future<void> addGroup()async{final n=TextEditingController(),d=TextEditingController();await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Tambah Kelompok'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Nama Kelompok *')),TextField(controller:d,decoration:const InputDecoration(labelText:'Keterangan'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Batal')),FilledButton(onPressed:()async{if(n.text.trim().isNotEmpty){await AppDatabase.instance.addGroup(n.text.trim(),d.text.trim());if(mounted)Navigator.pop(context);await load();}},child:const Text('Simpan'))]));}Future<void> addSub()async{if(selected==null)return;final n=TextEditingController();await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Tambah Subkelompok'),content:TextField(controller:n,decoration:const InputDecoration(labelText:'Nama Subkelompok *',hintText:'Kelompok 1')),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Batal')),FilledButton(onPressed:()async{if(n.text.trim().isNotEmpty){try{await AppDatabase.instance.addSubgroup(selected!,n.text.trim());if(mounted)Navigator.pop(context);await loadSubs(selected!);}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Subkelompok dengan nama tersebut sudah ada.')));}}},child:const Text('Simpan'))]));}Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('Kelompok Pengajian',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),FilledButton.icon(onPressed:widget.role==AppRole.anggota?null:addGroup,icon:const Icon(Icons.add),label:const Text('Tambah'))]),const SizedBox(height:12),...data.map((g)=>Card(child:ListTile(selected:selected==g['id'],leading:CircleAvatar(child:Text('${g['id']}')),title:Text('${g['name']}'),subtitle:Text((g['is_active']==1?'Aktif':'Nonaktif')+' • pilih untuk melihat subkelompok'),trailing:Switch(value:g['is_active']==1,onChanged:widget.role==AppRole.anggota?null:(v)async{await AppDatabase.instance.toggleGroup(g['id'] as int,v);load();}),onTap:()async{selected=g['id'] as int;await loadSubs(selected!);setState((){});}))),if(selected!=null)Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('Subkelompok',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),IconButton(onPressed:widget.role==AppRole.anggota?null:addSub,icon:const Icon(Icons.add_circle_outline))]),if(subs.isEmpty)const Text('Belum ada subkelompok.'),...subs.map((s)=>ListTile(contentPadding:EdgeInsets.zero,title:Text('${s['name']}'),subtitle:Text(s['is_active']==1?'Aktif':'Nonaktif'),trailing:Switch(value:s['is_active']==1,onChanged:widget.role==AppRole.anggota?null:(v)async{await AppDatabase.instance.toggleSubgroup(s['id'] as int,v);loadSubs(selected!);})))])))]);}
class MembersPage extends StatefulWidget{final AppRole role;const MembersPage({super.key,required this.role});State<MembersPage> createState()=>_MembersPageState();}
class _MembersPageState extends State<MembersPage>{List<Map<String,Object?>> data=[];@override void initState(){super.initState();load();}Future<void> load()async{final d=await AppDatabase.instance.members();if(!mounted)return;setState(()=>data=d);}Future<void> add()async{final code=TextEditingController(),name=TextEditingController(),phone=TextEditingController(),addr=TextEditingController();await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Tambah Anggota'),content:SingleChildScrollView(child:Column(children:[TextField(controller:code,decoration:const InputDecoration(labelText:'Kode Anggota *')),TextField(controller:name,decoration:const InputDecoration(labelText:'Nama *')),TextField(controller:phone,decoration:const InputDecoration(labelText:'No. HP')),TextField(controller:addr,decoration:const InputDecoration(labelText:'Alamat'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Batal')),FilledButton(onPressed:()async{if(code.text.trim().isNotEmpty&&name.text.trim().isNotEmpty){try{await AppDatabase.instance.addMember(code.text.trim(),name.text.trim(),phone.text.trim(),addr.text.trim());if(mounted)Navigator.pop(context);load();}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Kode anggota sudah digunakan.')));}}},child:const Text('Simpan'))]));}Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('Data Anggota',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),FilledButton.icon(onPressed:widget.role==AppRole.anggota?null:add,icon:const Icon(Icons.add),label:const Text('Tambah'))]),const SizedBox(height:12),...data.map((m)=>Card(child:ListTile(leading:CircleAvatar(child:Text('${m['name']}'.substring(0,1).toUpperCase())),title:Text('${m['name']}'),subtitle:Text('${m['member_code']} • ${m['group_name']??'Belum ditempatkan'}${m['subgroup_name']==null?'':' / ${m['subgroup_name']}'}'),trailing:Switch(value:m['is_active']==1,onChanged:widget.role==AppRole.anggota?null:(v)async{await AppDatabase.instance.toggleMember(m['id'] as int,v);load();}))))]);}}
